import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { QUANTITY_ENVELOPE } from '../src/generated/quantityEnvelope';
import type { ContractQuantityDeclaration } from '../src/generated/moduleRegistry';
import {
  checkedObservation,
  checkedQuantity,
  checkedQuantityContainer,
  checkedValueProvenance,
  containerProblems,
  parentKey,
  reasonText,
  sourceLabel,
  sourceLabelText,
} from '../src/data/quantityEnvelope';

// Fixtures are generated by python/tools/quantity_envelope_fixtures.py (synthetic, test path only) and checked
// against python/quantity_envelope.py by python/test_quantity_envelope.py, so both validators see the same payloads.
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- the tests mutate fixture payloads freely
type Json = Record<string, any>;
const fixture = (name: string): Json =>
  JSON.parse(readFileSync(new URL(`./fixtures/quantity-envelope/${name}`, import.meta.url), 'utf8')) as Json;
const clone = <T>(value: T): T => structuredClone(value);

function rejects(doc: Json, fragment: string): void {
  const problems = containerProblems(doc);
  assert.ok(problems.some(problem => problem.includes(fragment)), `expected "${fragment}" in ${JSON.stringify(problems)}`);
  assert.throws(() => checkedQuantityContainer(doc), /quantity container rejected/);
}

test('generated vocabularies: 25 reason codes, the P8 kind enum, screening-only ceiling, no Production', () => {
  assert.equal(QUANTITY_ENVELOPE.reasonCodes.length, 25);
  assert.deepEqual(QUANTITY_ENVELOPE.reasonCodes.slice(21), ['parent-unavailable', 'solver-error', 'insufficient-sample-support', 'quarantined-legacy-path']);
  assert.deepEqual([...QUANTITY_ENVELOPE.inputKinds].sort(), ['alloyTransfer', 'declaredAssumption', 'derived', 'followsInput', 'legacyEstimate',
    'modelConvention', 'sourceDefault', 'sourceModelAssumption', 'sourcedAlternative', 'userInput']);
  assert.equal(QUANTITY_ENVELOPE.moduleEvidenceCeiling, 'screening-only');
  assert.deepEqual(QUANTITY_ENVELOPE.moduleMaturities, ['Research', 'Preview']);
  assert.ok(!(QUANTITY_ENVELOPE.quantitySourceEvidenceKinds as readonly string[]).includes('Measured'));
  for (const code of QUANTITY_ENVELOPE.reasonCodes) assert.match(reasonText(code), /^[A-Z].*\.$/);
  assert.equal(sourceLabelText('User input', ['conductivity_W_mK']), 'User input: conductivity_W_mK');
  assert.equal(sourceLabelText('Unresolved', ['liquidus_K', 'k']), 'Unresolved: liquidus_K, k');
  assert.equal(sourceLabelText('Measured'), 'Measured (transcribed)');
});

test('the TypeScript label rule matches the Python label cases (decisions 1 and 2)', () => {
  const { cases } = fixture('label-cases.json');
  assert.ok(cases.length >= 14);
  for (const item of cases) {
    const result = sourceLabel(item.inputs, item.dependsOn);
    assert.deepEqual({ sourceEvidenceKind: result.sourceEvidenceKind, weakestInputs: result.weakestInputs, labelSources: result.labelSources },
      item.expected, item.name);
    for (const [name, record] of Object.entries(item.inputs)) checkedValueProvenance(record, `${item.name}.${name}`);
  }
  const named = Object.fromEntries(cases.map((item: Json) => [item.name, item.expected.sourceEvidenceKind]));
  assert.equal(named['unresolved-takes-precedence'], 'Unresolved');
  assert.equal(named['process-values-excluded'], 'Literature estimate');
  assert.equal(named['process-only-never-upgraded'], 'Unresolved');
  assert.equal(named['typed-equal-to-default-keeps-source'], 'Literature estimate');
  assert.equal(named['typed-different-is-user-input'], 'User input');
});

test('the shared value-provenance parser refuses Measured inputs, unlocated sources and unknown keys', () => {
  const { inputProvenance } = fixture('synthetic-admitted-liquidus.json');
  const transfer = checkedValueProvenance(inputProvenance.liquidus_K);
  assert.equal(transfer.kind, 'alloyTransfer');
  assert.equal(transfer.sourceEvidenceKind, 'Literature estimate');
  assert.equal(transfer.status, 'extrapolated');
  assert.throws(() => checkedValueProvenance({ ...transfer, sourceEvidenceKind: 'Measured' }), /never reads Measured/);
  assert.throws(() => checkedValueProvenance({ ...transfer, status: 'inRange' }), /never inRange/);
  assert.throws(() => checkedValueProvenance({ ...transfer, sourceLocator: null }), /located source/);
  assert.throws(() => checkedValueProvenance({ ...transfer, weakestInputs: [] }), /unknown keys weakestInputs/);
  assert.throws(() => checkedValueProvenance({ ...inputProvenance.power_W, sourceEvidenceKind: 'Literature estimate' }), /cannot read/);
});

test('F16: the synthetic admitted-liquidus fixture is accepted with co-located full-precision values', () => {
  const doc = fixture('synthetic-admitted-liquidus.json');
  const container = checkedQuantityContainer(doc, { moduleMaturity: 'Research' });
  const q = container.quantities;
  const g = q.thermalGradient.value as number;
  const r = q.normalSpeed.value as number;
  assert.equal(g, 12345678.901234567);
  assert.equal(r, 0.051234567890123456);
  assert.equal(q.coolingRate.value, g * r);
  assert.equal(q.gOverR.value, g / r);
  for (const [name, item] of Object.entries(q)) {
    assert.equal(item.sourceEvidenceKind, 'Literature estimate', name);
    assert.ok(item.labelSources.length > 0, name);
    assert.equal(item.identity.parent, parentKey(doc.inputProvenance, item.dependsOn, doc.quantities), name);
    checkedQuantity(item, { inputs: doc.inputProvenance, quantities: doc.quantities });
  }
  assert.equal(container.moduleEvidenceCeiling, 'screening-only');
});

test('F16 negative mutations: each one is rejected on its own', () => {
  const base = fixture('synthetic-admitted-liquidus.json');
  const mutate = (change: (doc: Json) => void): Json => { const doc = clone(base); change(doc); return doc; };
  rejects(mutate(d => { d.quantities.thermalGradient.status = 'unavailable'; }), 'must carry value null');
  rejects(mutate(d => { d.quantities.thermalGradient.value = null; }), 'needs a value');
  rejects(mutate(d => { d.quantities.normalSpeed.identity.model = null; }), 'engine/model identity');
  rejects(mutate(d => { d.quantities.normalSpeed.identity.parent = null; }), 'parent identity');
  rejects(mutate(d => { d.quantities.normalSpeed.quantityDefinition = 'liquidus-speed'; }), 'not a registered definition');
  rejects(mutate(d => { d.quantities.normalSpeed.unit = 'mm/s'; }), 'unit must be');
  rejects(mutate(d => { delete d.quantities.normalSpeed.unit; }), 'missing keys');
  rejects(mutate(d => { d.quantities.gOverR.sourceEvidenceKind = null; }), 'per-value source label');
  rejects(mutate(d => { d.quantities.gOverR.labelSources = []; }), 'labelSources');
  rejects(mutate(d => { d.quantities.gOverR.dependsOn = []; }), 'names the inputs');
  // Forbidden evidence upgrade: the label rule, not the producer, decides the label.
  rejects(mutate(d => {
    d.inputProvenance.conductivity_W_mK = { ...d.inputProvenance.conductivity_W_mK, kind: 'declaredAssumption',
      sourceEvidenceKind: 'Unresolved', declarationLocator: 'synthetic declaration', defaultKind: null };
  }), 'differs from the label rule');
  rejects(mutate(d => { d.quantities.thermalGradient.sourceEvidenceKind = 'Measured'; }), 'Measured never labels a quantity');
  rejects(mutate(d => { d.moduleEvidenceCeiling = 'literature-estimate'; }), 'decision 1');
  rejects(mutate(d => { d.moduleMaturity = 'Production'; }), 'moduleMaturity');
  rejects(mutate(d => { d.quantities.thermalGradient.physicalValidation.experimentalValidation = true; }), 'physicalValidation');
  // Stale parent presented as current: a new endpoint record moves the parent key even with equal numbers.
  rejects(mutate(d => { d.inputProvenance.liquidus_K.sourceId = 'synthetic-f16:liquidus:other-record'; }), 'stale-parent value is not current');
  // Parent refusal propagates null and a reason to every dependent.
  rejects(mutate(d => {
    Object.assign(d.quantities.thermalGradient, { status: 'unavailable', value: null, sourceEvidenceKind: null, weakestInputs: [],
      labelSources: [], sources: [], uncertainty: null,
      reasons: [{ code: 'missing-source-constant', params: {}, parent: { input: 'liquidus_K', kind: 'alloyTransfer' } }],
      identity: { input: null, model: null, parent: null } });
  }), "parent quantity thermalGradient is null");
  rejects(mutate(d => { d.quantities.thermalGradient.value = 0; }), 'must be positive');
  rejects(mutate(d => { Object.assign(d.inputProvenance.liquidus_K,
    { kind: 'legacyEstimate', sourceEvidenceKind: 'Unresolved', phase: 'process' }); }), 'only userInput');
  for (const leafRole of ['convention', 'requestInput', 'softwareLimit', 'indexConvention']) {
    rejects(mutate(d => { Object.assign(d.quantities.thermalGradient,
      { leafRole, sourceEvidenceKind: null, weakestInputs: [], labelSources: [] }); }), 'requires a labelled role');
  }
  for (const field of ['value', 'model', 'both']) {
    rejects(mutate(d => {
      if (field !== 'model') d.quantities.thermalGradient.value = 1.2e7;
      if (field !== 'value') d.quantities.thermalGradient.identity.model = 'changed-model';
    }), 'stale-parent');
  }
  for (const [field, value] of Object.entries({ kind: 'sourceModelAssumption', scope: 'changed scope', status: 'outOfRange',
    sourceLocator: 'changed source', defaultKind: 'sourceModelAssumption', defaultValue: 26 })) {
    rejects(mutate(d => { d.inputProvenance.conductivity_W_mK[field] = value; }), 'stale-parent');
  }
});

test('process exclusion uses fixed request names; only userInput permits process phase', () => {
  const { cases } = fixture('label-cases.json');
  const sourced = cases[0].inputs.k;
  const user = cases.find((item: Json) => item.name === 'one-user-input').inputs.cp;
  const inputs = { k: sourced, power_W: { ...user, phase: null } };
  assert.equal(sourceLabel(inputs, Object.keys(inputs)).sourceEvidenceKind, 'Literature estimate');
  for (const name of QUANTITY_ENVELOPE.requestProcessInputs) {
    for (const phase of [null, 'solid', 'process']) {
      assert.equal(sourceLabel({ k: sourced, [name]: { ...user, phase } }, ['k', name]).sourceEvidenceKind, 'Literature estimate');
    }
  }
  const assumption = cases.find((item: Json) => item.name === 'unresolved-takes-precedence').inputs.k;
  const emissivity = { ...assumption, phase: 'process' };
  const label = sourceLabel({ emissivity }, ['emissivity']);
  assert.equal(sourceLabelText(label.sourceEvidenceKind, label.weakestInputs), 'Unresolved: emissivity');
  for (const kind of QUANTITY_ENVELOPE.inputKinds) {
    const record = { ...sourced, kind, phase: 'process' };
    if (kind === 'userInput') checkedValueProvenance({ ...record, sourceEvidenceKind: 'User input' });
    else assert.throws(() => checkedValueProvenance(record), /only userInput/);
  }
});

test('sourcedAlternative requires an explicitly non-default sensitivity container', () => {
  const base = fixture('synthetic-admitted-liquidus.json');
  const record = { ...base.inputProvenance.conductivity_W_mK, kind: 'sourcedAlternative', defaultKind: null };
  const doc = { ...base, quantities: {}, inputProvenance: { alternative: record } };
  for (const flag of [undefined, true, 0, 'false']) {
    rejects({ ...doc, default: flag }, 'container default: false');
  }
  checkedQuantityContainer({ ...doc, default: false });
  assert.throws(() => checkedValueProvenance({ ...record, defaultKind: 'sourcedAlternative' }), /never a defaultKind/);
});

test('the blanket-null front (SOL-A1 shape) is accepted and its parent chain is enforced', () => {
  const base = fixture('blanket-null-front.json');
  const container = checkedQuantityContainer(base);
  for (const name of ['thermalGradient', 'normalSpeed', 'coolingRate', 'gOverR', 'pdas']) {
    const item = container.quantities[name];
    assert.equal(item.value, null, name);
    assert.equal(item.sourceEvidenceKind, null, name);
    assert.deepEqual(item.reasons[0], { code: 'missing-source-constant', params: {}, parent: { input: 'liquidus_K', kind: 'declaredAssumption' } });
  }
  const mutate = (change: (doc: Json) => void): Json => { const doc = clone(base); change(doc); return doc; };
  rejects(mutate(d => { d.quantities.coolingRate.reasons.pop(); }), 'must name the null parent normalSpeed');
  rejects(mutate(d => { d.quantities.normalSpeed.reasons[0].parent.kind = 'sourceDefault'; }), 'differs from the input record');
  rejects(mutate(d => { d.quantities.normalSpeed.reasons = []; }), 'needs at least one reason');
  rejects(mutate(d => { d.quantities.normalSpeed.reasons[0].text = 'A producer sentence.'; }), 'no text from producers');
  rejects(mutate(d => { d.quantities.pdas.sources = [{ id: 'hunt-lu', locator: 'Hunt-Lu 1996', readLevel: 'secondary-read' }]; }), 'no source claim');
  rejects(mutate(d => { d.quantities.morphology.status = 'computed'; d.quantities.morphology.value = 'cellular'; }), 'no admitted category');
  rejects(mutate(d => { d.quantities.thermalGradient.uncertainty = { kind: 'not-quantified', construction: null }; }), 'no uncertainty');
  rejects(mutate(d => { d.quantities.thermalGradient.identity.parent = 'stale'; }), 'no parent identity');
  rejects(mutate(d => { d.quantities.thermalGradient.dependsOn = []; }), 'blocking input or sibling');
});

test('observations may read Measured; declarations bound statuses, labels and reason codes', () => {
  const mp05 = {
    recordKind: 'source-observation', observable: 'DSC operational temperatures of evaporating SRM316L', value: { Ts: 1675, Tl: 1708 },
    unit: 'K', sourceEvidenceKind: 'Measured', sources: [{ id: 'MP05', locator: 'Pichler et al. Table 2', readLevel: 'primary-read' }],
    materialScope: 'SRM316L (evaporating)', processScope: 'DSC heating', comparability: 'context-only',
  };
  assert.equal(checkedObservation(mp05).sourceEvidenceKind, 'Measured');
  assert.throws(() => checkedObservation({ ...mp05, sourceEvidenceKind: 'User input' }), /sourceEvidenceKind/);
  assert.throws(() => checkedObservation({ ...mp05, sources: [] }), /names its source/);
  assert.throws(() => checkedObservation(mp05, { path: 'front.observations.dsc', observable: 'other', sourceEvidenceKinds: ['Measured'] }), /observable differs/);
  const doc = fixture('synthetic-admitted-liquidus.json');
  const declaration: ContractQuantityDeclaration = {
    path: 'front.quantities.thermalGradient', definition: 'liquidus-front-thermal-gradient', unit: 'K/m',
    statuses: ['computed', 'unavailable'], sourceEvidenceKinds: ['Literature estimate'], reasonCodes: ['missing-source-constant'],
    fractionBasis: null, leafRole: 'derived',
  };
  const context = { inputs: doc.inputProvenance, quantities: doc.quantities };
  assert.equal(checkedQuantity(doc.quantities.thermalGradient, context, declaration).status, 'computed');
  assert.throws(() => checkedQuantity(doc.quantities.thermalGradient, context, { ...declaration, statuses: ['unavailable'] }), /status computed is not declared/);
  assert.throws(() => checkedQuantity(doc.quantities.thermalGradient, context, { ...declaration, sourceEvidenceKinds: ['User input'] }), /is not declared/);
  const declarations = { thermalGradient: declaration };
  assert.ok(containerProblems(doc, 'container', { quantityDeclarations: declarations }).some(problem => problem.includes('normalSpeed: not declared')));
});
